KURS = dict(
    id="u02", gebiet="upc", titel="Zuständigkeit und Kammerwahl",
    untertitel="Brüssel-Ia-VO, Art. 32 und 33 EPGÜ, dieselben Parteien, die drei Optionen bei der Widerklage und der Einspruch nach R. 19 bis 21 VerfO",
    farbe="#6a3d8f", icon="zulaessigkeit",
    beschreibung="Vier Stufen der Zuständigkeitsprüfung vor dem EPG: internationale Zuständigkeit nach der Brüssel-Ia-VO (Sinocare/Abbott, Dyson/Dreame, NUC/Hurom), sachliche Zuständigkeit nach Art. 32 EPGÜ, die richtige Kammer nach Art. 33 EPGÜ (Barco/Yealink, Meril/Edwards, Seoul Viosys/Emporia, Pari/Philips) und die Rüge durch den Einspruch (Roku/Dolby, Vivo/Sun Patent, Sun Patent/Vivo).",
    kapitel=[
        dict(id="u02a", titel="Ob und wo: internationale, sachliche und Kammerzuständigkeit", einheiten=[
            schema("u02a-0", "Prüfungsschema: Zuständigkeit des EPG", "upc_schema_zustaendigkeit",
                   "Von der Anwendbarkeit des EPGÜ über die internationale und sachliche Zuständigkeit bis zur Kammerwahl und zum Einspruch des Beklagten – in dieser Reihenfolge prüft die Klausur, und in dieser Reihenfolge verlangt R. 13.1 lit. i VerfO die Angaben in der Klageschrift."),
            intro("u02a-1", "Zuständigkeit in vier Stufen",
                  "**Erstens** die Anwendbarkeit des EPGÜ: Einheitspatent oder Bündelpatent ohne Opt-out (Art. 3, 83 EPGÜ). **Zweitens** die internationale Zuständigkeit: Art. 31 EPGÜ verweist auf die **Brüssel-Ia-VO**, die das EPG in Art. 71a bis 71d als gemeinsames Gericht behandelt. Zuständig ist es für Beklagte mit Sitz in einem Mitgliedstaat (Art. 4) und – unabhängig vom Sitz – für Verletzungen im Gebiet der Vertragsmitgliedstaaten (Art. 7 Nr. 2 i.V.m. Art. 71b Nr. 2): Der Schadensort liegt dort, wo verletzende Produkte für den Markt bestimmt sind und über Dritte erworben werden, auch wenn der Beklagte im Drittstaat handelt (Sinocare/Abbott; Dyson/Dreame). Wer sich einlässt, ohne zu rügen, begründet die Zuständigkeit (Art. 26 Brüssel-Ia-VO) – aber erst mit dem ersten Schriftsatz, nicht mit dem Zugriff auf das CMS (NUC/Hurom). **Drittens** die sachliche Zuständigkeit: Art. 32 Abs. 1 EPGÜ zählt abschließend auf (Verletzung, negative Feststellung, einstweilige Maßnahmen, Nichtigkeit, Widerklage, vorläufiger Schutz, Vorbenutzung, Lizenzvergütung, EPA-Entscheidungen); alles andere – Vindikation, Arbeitnehmererfindung, Lizenzvertrag – bleibt bei den nationalen Gerichten (Abs. 2). **Viertens** die Kammer: Verletzungsklagen zur Lokal- oder Regionalkammer am **Verletzungsort** oder am **Beklagtensitz** (Art. 33 Abs. 1), Nichtigkeits- und Feststellungsklagen zur **Zentralkammer** (Abs. 4). Die erste Tabelle sortiert die Klagearten, die zweite zeigt, wie der Beklagte die Zuständigkeit rügt: mit dem **Einspruch** (R. 19) binnen eines Monats, nicht erst in der Klageerwiderung (R. 23).",
                  concepts=["upc_internationale_zustaendigkeit", "upc_sachliche_zustaendigkeit", "upc_kammerzustaendigkeit"],
                  norms=["Art. 31 EPGÜ", "Art. 32 EPGÜ", "Art. 33 EPGÜ", "R. 19 VerfO"],
                  cases=["upc_coa_sinocare_abbott_zustaendigkeit", "upc_coa_nuc_hurom_einlassung"],
                  distinctions=["d_upc_lokalkammer_zentralkammer", "d_upc_einspruch_klageerwiderung"]),
            fall("u02a-2", "Hergestellt in Shenzhen, verkauft in Europa",
                 "Die A-Ltd. mit Sitz in Hongkong stellt in China Blutzuckersensoren her und verkauft sie an einen Zwischenhändler in Singapur. Der liefert an Vertriebsgesellschaften in Deutschland, Frankreich und den Niederlanden, wo die Sensoren – in Verpackungen mit CE-Kennzeichen und deutscher Gebrauchsanweisung – an Apotheken gehen. Die Patentinhaberin B verklagt die A-Ltd. vor einer deutschen Lokalkammer. Die A-Ltd. erhebt Einspruch: Sie habe keine Niederlassung in Europa und alle Handlungen außerhalb des EPG-Gebiets vorgenommen.",
                 "Ist das EPG international zuständig?", True,
                 ["**Ja!** Die internationale Zuständigkeit richtet sich nach der Brüssel-Ia-VO (Art. 31 EPGÜ). Gegen Beklagte ohne Sitz in einem Mitgliedstaat ist das EPG zuständig, wenn der **Schadensort** im Gebiet der Vertragsmitgliedstaaten liegt (Art. 71b Nr. 2 i.V.m. Art. 7 Nr. 2 Brüssel-Ia-VO). Werden angeblich verletzende Produkte **für die Vertragsmitgliedstaaten hergestellt und verkauft**, droht dort ein Schaden durch den Erwerb über Dritte, auch wenn die Handlungen selbst außerhalb des Gebiets vorgenommen werden (Sinocare/Abbott). Die CE-Kennzeichnung und die deutsche Gebrauchsanweisung zeigen die Marktbestimmung.",
                  "Die Lokalkammer Hamburg hat ebenso entschieden: Das EPG ist als gemeinsames Gericht unabhängig vom Sitz des Beklagten für alle Verletzungen in einem Vertragsmitgliedstaat zuständig; mehrere Beklagte desselben Konzerns, die dieselben Ausführungsformen vertreiben, können nach Art. 8 Nr. 1 Brüssel-Ia-VO gemeinsam verklagt werden (Dyson/Dreame). Von der internationalen Zuständigkeit zu trennen ist die **Kammerwahl**: Gegen Drittstaatenbeklagte kann am Verletzungsort oder bei der Zentralkammer geklagt werden (Art. 33 Abs. 1 UAbs. 3 EPGÜ)."],
                 merke="Wer für den europäischen Markt produziert, verletzt dort: Der Schadensort nach Art. 7 Nr. 2 Brüssel-Ia-VO holt den Drittstaatenbeklagten vor das EPG.",
                 level=2, concepts=["upc_internationale_zustaendigkeit"],
                 norms=["Art. 31 EPGÜ", "Art. 33 Abs. 1 EPGÜ"],
                 cases=["upc_coa_sinocare_abbott_zustaendigkeit", "upc_cfi_dyson_dreame_zustaendigkeit"], step="step:upc_schema_zustaendigkeit.2"),
            fall("u02a-3", "Der Blick ins CMS",
                 "Die koreanische H-Co. wird vor einer Lokalkammer verklagt. Die Kanzlei stellt die Klageschrift mit einem Zugangscode zu; der Vertreter der H-Co. ruft die Akte im elektronischen Fallbearbeitungssystem (CMS) ab und lädt die Klageschrift herunter. Drei Wochen später erhebt die H-Co. Einspruch nach R. 19 VerfO und rügt die fehlende internationale Zuständigkeit. Die Klägerin meint, durch den Zugriff auf das CMS habe sich die H-Co. bereits rügelos eingelassen (Art. 26 Brüssel-Ia-VO).",
                 "Liegt in dem Zugriff auf das CMS eine rügelose Einlassung?", False,
                 ["**Nein!** Nach Art. 26 Abs. 1 Brüssel-Ia-VO wird das Gericht zuständig, wenn sich der Beklagte auf das Verfahren einlässt, ohne den Mangel der Zuständigkeit zu rügen. Im **elektronischen Verfahren** des EPG (Art. 44 EPGÜ, R. 4.1 VerfO) ist der Zugriff auf die Akte mit dem zugestellten Zugangscode aber nur der technisch erste Schritt des Vertreters, um überhaupt Kenntnis von der Klage zu nehmen. Erst mit dem **ersten Schriftsatz** – dem Einspruch nach R. 19 VerfO oder der Klageerwiderung nach R. 23 ff. VerfO – entscheidet sich der Beklagte bewusst für oder gegen die Zuständigkeit (NUC/Hurom).",
                  "Die H-Co. hat binnen eines Monats nach Zustellung Einspruch erhoben (R. 19.1 VerfO); ihre Rüge ist rechtzeitig. Hätte sie den Einspruch versäumt, gälte die Zuständigkeit als anerkannt (R. 19.7 VerfO), und die Rüge wäre auch in der Berufung verloren (Sinocare/Abbott)."],
                 merke="Einlassung ist eine Prozesserklärung, kein Download: Erst Einspruch oder Klageerwiderung entscheiden über die Zuständigkeit.",
                 level=2, concepts=["upc_einlassung", "upc_einspruch_r19"],
                 norms=["Art. 31 EPGÜ", "R. 19.1 VerfO", "R. 19.7 VerfO", "R. 4 VerfO"],
                 cases=["upc_coa_nuc_hurom_einlassung", "upc_coa_sinocare_abbott_zustaendigkeit"], step="step:upc_schema_zustaendigkeit.2"),
            fall("u02a-4", "Die Website ist überall abrufbar",
                 "Die B-NV beantragt bei der Lokalkammer Hamburg einstweilige Maßnahmen gegen die chinesische Y-Ltd. und deren deutschen Vertriebspartner V-GmbH mit Sitz in München. Die Y-Ltd. bietet die angegriffenen Konferenzsysteme über eine in Deutschland abrufbare, deutschsprachige Website an. Die Beklagten rügen die Kammerzuständigkeit: Die V-GmbH habe ihren Sitz in München, weshalb Art. 33 Abs. 1 lit. b EPGÜ vorrangig sei; außerdem sei keine Verletzung gerade in Hamburg bewiesen.",
                 "Ist die Lokalkammer Hamburg zuständig?", True,
                 ["**Ja!** Art. 33 Abs. 1 EPGÜ eröffnet dem Kläger die Wahl zwischen der Lokalkammer des Vertragsmitgliedstaats, in dem die Verletzung erfolgt ist oder droht (lit. a), und der des Beklagtensitzes (lit. b); zwischen beiden besteht **keine Rangfolge** (Barco/Yealink). Für lit. a kommt es auf den **Vertragsmitgliedstaat** an, nicht auf den Kammerbezirk innerhalb Deutschlands. Bei mehreren Beklagten genügt die Feststellung von Verletzungshandlungen im Gebiet, etwa ein **Angebot über eine dort abrufbare Website**; die Zuständigkeitsprüfung ist kursorisch, keine volle Beweisaufnahme.",
                  "Die Kammerzuständigkeit ist eine interne Frage des EPG außerhalb der Brüssel-Ia-VO. Wäre die gewählte Kammer unzuständig, würde die Klage nicht abgewiesen, sondern auf Angabe einer zuständigen Kammer durch den Kläger verwiesen (R. 19.5 VerfO), und zwar aus Effizienzgründen auch im Verfahren auf einstweilige Maßnahmen (Barco/Yealink). Eine Klage gegen mehrere Beklagte setzt eine Geschäftsbeziehung und denselben Verletzungsvorwurf voraus (Art. 33 Abs. 1 UAbs. 2 EPGÜ)."],
                 merke="Verletzungsort oder Sitz, der Kläger wählt; das Angebot auf einer abrufbaren Website genügt, und die falsche Kammer führt zur Verweisung, nicht zur Abweisung.",
                 level=2, concepts=["upc_kammerzustaendigkeit", "upc_anbieten"],
                 norms=["Art. 33 Abs. 1 EPGÜ", "R. 19.5 VerfO", "R. 13 VerfO"],
                 cases=["upc_coa_barco_yealink_kammer"], step="step:upc_schema_zustaendigkeit.4.1"),
            mc("u02a-5", "Dieselben Parteien",
               "Die Patentinhaberin E führt vor einer Lokalkammer eine Verletzungsklage gegen die indische M-Ltd. und deren deutsche Tochter M-GmbH. Kurz darauf erhebt die italienische Schwestergesellschaft M-Srl bei der Zentralkammer Nichtigkeitsklage gegen dasselbe Patent. E rügt: Wegen der anhängigen Verletzungsklage sei die Zentralkammer nach Art. 33 Abs. 4 EPGÜ unzuständig. Wann sind M-Srl und die Beklagten der Verletzungsklage „dieselben Parteien“?",
               ["Immer, wenn die Gesellschaften demselben Konzern angehören, weil die Konzernmutter die Prozessführung steuert",
                "Nur bei Identität der Rechtsträger; ausnahmsweise, wenn die Interessen so identisch sind, dass ein Urteil gegen den einen Rechtskraft gegen den anderen entfalten würde – Konzernverbundenheit oder eine abgestimmte Verteidigungsstrategie genügen nicht",
                "Nie, weil Art. 33 Abs. 4 EPGÜ nur natürliche Personen meint",
                "Wenn die Nichtigkeitsklägerin dieselben Vertreter beauftragt hat wie die Verletzungsbeklagten"], 1,
               ["Art. 33 Abs. 4 EPGÜ nimmt der Zentralkammer die Zuständigkeit für die Nichtigkeitsklage, wenn **zwischen denselben Parteien zum selben Patent** bereits eine Verletzungsklage bei einer Lokal- oder Regionalkammer anhängig ist; dann ist nur diese Kammer zuständig. „Dieselben Parteien“ verlangt grundsätzlich **Identität** der Rechtsträger. Zwei Rechtsträger gelten ausnahmsweise als eine Partei, wenn ihre Interessen so identisch sind, dass ein Urteil gegen den einen **Rechtskraft** gegen den anderen entfalten würde (Meril/Edwards). Bloße Konzernverbundenheit reicht nicht.",
                "Die Zentralkammer Paris hat dazu die aus dem Unionsrecht stammende **Strohmann-Theorie** herangezogen: Sie kann das Merkmal ausfüllen, aber eine gemeinsame Verteidigungsstrategie zweier Unternehmen gegen die Verletzungsklage macht das zweite noch nicht zum Strohmann des ersten (Seoul Viosys/Emporia). Die M-Srl darf also klagen; die Lokalkammer kann die parallele Nichtigkeitsklage bei ihrer Entscheidung nach Art. 33 Abs. 3 EPGÜ und R. 118.2 VerfO berücksichtigen. Für die Sperre paralleler Verletzungsklagen zwischen denselben Parteien gilt Art. 33 Abs. 2 EPGÜ: Die zuerst angerufene Kammer ist zuständig."],
               merke="Dieselben Parteien heißt dieselben Rechtsträger; die Ausnahme verlangt Rechtskrafterstreckung, nicht Konzernzugehörigkeit.",
               level=3, concepts=["upc_dieselben_parteien", "upc_zentralkammer"],
               norms=["Art. 33 Abs. 4 EPGÜ", "Art. 33 Abs. 2 EPGÜ"],
               cases=["upc_coa_meril_edwards_parteien", "upc_cfi_seoulviosys_emporia_strohmann"], step="step:upc_schema_zustaendigkeit.4.2"),
            fall("u02a-6", "Drei Wege bei der Widerklage",
                 "Die Beklagte erhebt vor der Lokalkammer Düsseldorf in der Klageerwiderung Widerklage auf Nichtigerklärung. Nach Abschluss des schriftlichen Verfahrens beschließt der Spruchkörper – drei rechtlich qualifizierte Richter – ohne Anhörung der Parteien, Verletzungsklage und Widerklage gemeinsam zu verhandeln und zu entscheiden; einen technisch qualifizierten Richter fordert er nicht an, weil die Technik einfach sei.",
                 "Ist das Vorgehen der Lokalkammer zulässig?", False,
                 ["**Nein!** Art. 33 Abs. 3 EPGÜ gibt der Lokal- oder Regionalkammer bei einer Widerklage auf Nichtigerklärung drei Optionen, über die sie **nach Anhörung der Parteien** nach Ermessen entscheidet (R. 37.1 VerfO, rechtliches Gehör nach R. 264): (a) beide Klagen selbst verhandeln **und** den Präsidenten des Gerichts erster Instanz ersuchen, einen **technisch qualifizierten Richter** aus dem Richterpool zuzuweisen; (b) die Widerklage an die Zentralkammer verweisen und das Verletzungsverfahren aussetzen oder fortführen (Bifurkation); (c) mit Zustimmung der Parteien den ganzen Fall an die Zentralkammer verweisen. Wählt die Kammer Option (a), ist der technische Richter zwingend anzufordern (R. 37.3 VerfO); ein Ermessen, auf ihn zu verzichten, gibt es nicht.",
                  "Die Lokalkammer hat zweimal gefehlt: Sie hat die Parteien nicht angehört und den technischen Richter nicht angefordert. In der Praxis wählen die Kammern fast immer Option (a) – das unterscheidet das EPG vom deutschen Trennungsprinzip (§ 81 PatG). Bei Option (b) soll das Verletzungsverfahren ausgesetzt werden, wenn die Nichtigerklärung hochwahrscheinlich ist (R. 37.4 VerfO), um die „injunction gap“ zu vermeiden. Widerklage und Verletzungsklage bleiben getrennte Klagen; die Widerklage kann unter die Bedingung der Verletzungsfeststellung gestellt werden (Emboline/AorticLab)."],
                 merke="Option (a) heißt: gemeinsam verhandeln, aber nur mit technischem Richter; die Wahl trifft die Kammer nach Anhörung der Parteien.",
                 level=2, concepts=["upc_widerklage_nichtigkeit", "upc_bifurkation", "upc_spruchkoerper"],
                 norms=["Art. 33 Abs. 3 EPGÜ", "R. 37 VerfO", "Art. 8 Abs. 5 EPGÜ", "R. 25 VerfO"],
                 cases=["upc_coa_emboline_aorticlab_bedingte_widerklage"], step="step:upc_schema_zustaendigkeit.4.3"),
            fall("u02a-7", "Freedom to operate",
                 "Die P-GmbH entwickelt Inhalationsgeräte und will in zwei Jahren ein neues Modell auf den Markt bringen. Sie erhebt bei der Zentralkammer Nichtigkeitsklage gegen ein Patent der K-NV, ohne zuvor Einspruch beim EPA eingelegt zu haben und ohne dass die K-NV sie je abgemahnt hätte. Die K-NV rügt: Die P-GmbH sei vom Patent nicht „betroffen“ (Art. 47 Abs. 6 EPGÜ), weil sie noch kein Produkt vertreibe, und hätte zunächst das Einspruchsverfahren durchlaufen müssen.",
                 "Ist die Nichtigkeitsklage zulässig?", True,
                 ["**Ja!** Nichtigkeitsklagen gehören vor die Zentralkammer (Art. 32 Abs. 1 lit. d, Art. 33 Abs. 4 EPGÜ); die Zuweisung an Paris, München oder Mailand folgt der IPC-Klasse (Anhang II, R. 17.3 VerfO). Klagebefugt ist jede Person, die vom Patent **betroffen** und nach ihrem nationalen Recht klageberechtigt ist (Art. 47 Abs. 6 EPGÜ). Betroffen ist, wer seine **Freedom to operate** klären will – also jeder, der auf dem technischen Gebiet des Patents tätig ist oder werden könnte (ZK Mailand, Pari/Philips). Eine Abmahnung oder ein Produkt auf dem Markt ist nicht erforderlich; ein besonderes Rechtsschutzbedürfnis wie im deutschen Nichtigkeitsverfahren kennt das EPGÜ nicht.",
                  "Ein vorheriger Einspruch beim EPA ist ebenfalls keine Voraussetzung (Art. 33 Abs. 8 EPGÜ); läuft ein Einspruchsverfahren parallel, kann das Gericht aussetzen, wenn eine rasche EPA-Entscheidung zu erwarten ist (Art. 33 Abs. 10 EPGÜ, R. 295 lit. a VerfO). Die Klage muss nach R. 44 VerfO Umfang, Gründe, Tatsachen und Beweismittel vollständig enthalten (front-loaded)."],
                 merke="Betroffen ist, wer auf dem Gebiet arbeitet oder arbeiten will; Einspruch beim EPA ist keine Vorstufe zur Nichtigkeitsklage.",
                 level=1, concepts=["upc_zentralkammer", "upc_nichtigkeitsklage"],
                 norms=["Art. 47 Abs. 6 EPGÜ", "Art. 33 Abs. 4 EPGÜ", "Art. 33 Abs. 8 EPGÜ", "R. 44 VerfO"],
                 cases=["upc_cfi_pari_philips_klagebefugnis"], step="step:upc_schema_zustaendigkeit.4.4"),
        ]),
        dict(id="u02b", titel="Die Rüge: Einspruch nach R. 19 bis 21 VerfO", einheiten=[
            intro("u02b-0", "Preliminary objection: ein Monat, drei Gründe",
                  "Der Beklagte muss die Zuständigkeit **binnen eines Monats** nach Zustellung der Klageschrift mit dem **Einspruch** (Preliminary objection) rügen (R. 19.1 VerfO). Die Gründe sind abschließend: (a) Zuständigkeit des Gerichts einschließlich eines Opt-out, (b) Zuständigkeit der gewählten Kammer, (c) Sprache der Klageschrift; ein Verstoß gegen Art. 47 GRCh als solcher gehört nicht dazu (Roku/Dolby). Vor einer Regionalkammer kann der Beklagte zudem die Verweisung an die Zentralkammer verlangen, wenn die Verletzung in drei oder mehr Regionalkammern erfolgt ist (R. 19.4, Art. 33 Abs. 2 EPGÜ). Bleibt der Einspruch aus, gilt die Zuständigkeit von Gericht und Kammer als **anerkannt** (R. 19.7) – die Rüge ist dann auch in der Berufung verloren (Sinocare/Abbott). Die Frist für die Klageerwiderung läuft weiter (R. 19.6). Der Kläger kann Mängel der Kammerwahl oder Sprache binnen 14 Tagen selbst beheben; nennt er eine zuständige Kammer, **verweist** der Berichterstatter (R. 19.5). Über den Einspruch entscheidet der **Berichterstatter** nach rechtlichem Gehör (R. 20.1) oder er behandelt ihn im Hauptverfahren (R. 20.2) – das darf auch der Spruchkörper, wenn die Frage nach R. 102.1 an ihn verwiesen wurde (Vivo/Sun Patent). Gibt der Berichterstatter dem Einspruch statt, ist die Berufung nach R. 220.1 lit. a statthaft; weist er ihn zurück, nur mit Zulassung nach R. 220.2 (R. 21.1). Eine **Aussetzung** nach R. 21.2 setzt voraus, dass die Berufung bereits eingelegt ist (Sun Patent/Vivo).",
                  concepts=["upc_einspruch_r19", "upc_einlassung", "upc_berichterstatter"],
                  norms=["R. 19 VerfO", "R. 20 VerfO", "R. 21 VerfO", "R. 220.2 VerfO"],
                  cases=["upc_coa_roku_dolby_einspruch", "upc_coa_sinocare_abbott_zustaendigkeit"]),
            mc("u02b-1", "Was kann der Einspruch rügen?",
               "Die Beklagte will vor einer Lokalkammer den Einspruch nach R. 19 VerfO erheben. Welche der folgenden Rügen ist als Einspruchsgrund statthaft?",
               ["Das Patent sei offensichtlich nicht rechtsbeständig, weshalb die Klage ohne Verhandlung abzuweisen sei",
                "Für das Patent sei ein Opt-out im Register eingetragen, weshalb das EPG nicht zuständig sei",
                "Die Klageschrift enthalte keine Merkmalsanalyse und verstoße damit gegen R. 13.1 lit. m VerfO",
                "Die Klägerin sei als nicht ausschließliche Lizenznehmerin nicht klagebefugt (Art. 47 Abs. 3 EPGÜ)"], 1,
               ["R. 19.1 VerfO ist ein **abschließender Katalog**: Der Einspruch kann nur die Zuständigkeit des Gerichts – ausdrücklich einschließlich der Einwendung, dass ein **Opt-out** nach R. 5 auf das Patent Anwendung findet (lit. a) –, die Zuständigkeit der vom Kläger gewählten Kammer (lit. b) und die Sprache der Klageschrift (lit. c) betreffen. Zur Zuständigkeit des Gerichts gehört auch die Gültigkeit der Zuständigkeitsvorschriften, nicht aber ein Grundrechtsverstoß als solcher (Roku/Dolby).",
                "Rechtsbestand, Mängel der Klageschrift und Klagebefugnis sind keine Einspruchsgründe. Den Rechtsbestand greift der Beklagte mit der **Widerklage** in der Klageerwiderung an (R. 25 VerfO); formale Mängel der Klageschrift prüft die Kanzlei (R. 16 VerfO), und alle übrigen Einwendungen – auch die fehlende Klagebefugnis – gehören in die **Klageerwiderung** nach R. 23, 24 VerfO. Der Einspruch ist in der Sprache der Klageschrift zu verfassen (R. 19.3) und hemmt die Erwiderungsfrist nicht (R. 19.6)."],
               merke="Der Einspruch fragt nur: darf dieses Gericht, darf diese Kammer, in dieser Sprache? Alles andere gehört in die Klageerwiderung.",
               level=1, concepts=["upc_einspruch_r19", "upc_opt_out"],
               norms=["R. 19.1 VerfO", "R. 19.6 VerfO", "R. 23 VerfO", "R. 25 VerfO"],
               cases=["upc_coa_roku_dolby_einspruch"], step="step:upc_schema_zustaendigkeit.5"),
            fall("u02b-2", "Der Spruchkörper entscheidet",
                 "Die V-Corp. erhebt vor einer Lokalkammer Einspruch gegen die Zuständigkeit. Der Berichterstatter verweist die Frage nach R. 102.1 VerfO an den Spruchkörper. Dieser ordnet an, dass der Einspruch nicht vorab, sondern im Hauptverfahren behandelt wird. Die V-Corp. legt Berufung ein: Nach R. 20.2 VerfO könne nur der Berichterstatter diese Entscheidung treffen, und R. 102 gelte nur im Zwischenverfahren, nicht im schriftlichen Verfahren.",
                 "Durfte der Spruchkörper die Entscheidung nach R. 20.2 VerfO treffen?", True,
                 ["**Ja!** Nach R. 20 VerfO entscheidet der Berichterstatter über den Einspruch (Abs. 1) oder unterrichtet die Parteien, dass der Einspruch im Hauptverfahren behandelt wird (Abs. 2). Der Berichterstatter kann aber **jede Angelegenheit** an den Spruchkörper verweisen (R. 102.1 VerfO). R. 102 steht zwar im Abschnitt über das Zwischenverfahren, gilt aber im **schriftlichen Verfahren entsprechend**, weil der Berichterstatter nach R. 18 und R. 331.1 VerfO auch dort das Fallmanagement innehat – einschließlich der Befugnis, die Reihenfolge der zu entscheidenden Fragen festzulegen (R. 334 lit. e VerfO). Was der Berichterstatter darf, darf nach Verweisung auch der Spruchkörper (Vivo/Sun Patent).",
                  "Die Berufung hat auch deshalb wenig Aussicht, weil die Entscheidung, den Einspruch ins Hauptverfahren zu verweisen, keine Zurückweisung nach R. 21.1 Satz 2 ist, sondern eine verfahrensleitende Anordnung; sie ist nur mit Zulassung nach R. 220.2 VerfO oder im Wege der Ermessensüberprüfung angreifbar. Die Zuständigkeitsfrage wird dann in der Endentscheidung mitentschieden."],
                 merke="Der Berichterstatter managt das schriftliche Verfahren, darf aber alles dem Spruchkörper vorlegen – und der entscheidet dann in seiner Rolle.",
                 level=3, concepts=["upc_einspruch_r19", "upc_berichterstatter"],
                 norms=["R. 20 VerfO", "R. 102 VerfO", "R. 331 VerfO", "R. 334 VerfO"],
                 cases=["upc_coa_vivo_sunpatent_einspruch_hauptverfahren"], step="step:upc_schema_zustaendigkeit.5"),
            fall("u02b-3", "Aussetzung ohne Berufung",
                 "Der Berichterstatter weist den Einspruch der V-Corp. zurück. Die V-Corp. beantragt beim Gericht erster Instanz die Zulassung der Berufung nach R. 220.2 VerfO und zugleich, das Verfahren nach R. 21.2 VerfO bis zur Entscheidung des Berufungsgerichts auszusetzen. Berufung hat sie noch nicht eingelegt – die Zulassung steht ja aus. Hilfsweise stützt sie den Aussetzungsantrag auf R. 295 lit. m VerfO.",
                 "Kann das Verfahren nach R. 21.2 VerfO ausgesetzt werden?", False,
                 ["**Nein!** R. 21.2 VerfO erlaubt dem Berichterstatter oder dem Berufungsgericht die Aussetzung des erstinstanzlichen Verfahrens auf Antrag, „wird Berufung eingelegt“. Die Vorschrift setzt also voraus, dass die Berufung gegen die Einspruchsentscheidung **bereits eingelegt** ist; ein bloßer Zulassungsantrag nach R. 220.2 VerfO genügt nicht. Die Sonderregeln der R. 19 bis 21 gehen den allgemeinen Aussetzungsregeln der R. 295 ff. als leges speciales vor (Sun Patent/Vivo).",
                  "Auch der Hilfsantrag hilft der V-Corp. nicht weiter: R. 295 VerfO gilt zwar in beiden Instanzen, über die Aussetzung eines erstinstanzlichen Verfahrens entscheidet aber grundsätzlich das Gericht erster Instanz, das die Umstände besser kennt und Ermessen beim Fallmanagement hat (Sun Patent/Vivo). Die V-Corp. muss ihre Klageerwiderung fristgerecht einreichen (R. 19.6, R. 23 VerfO); der Einspruch hemmt die Frist nicht."],
                 merke="R. 21.2 setzt eine eingelegte Berufung voraus; die Sonderregeln zum Einspruch verdrängen R. 295, und die Erwiderungsfrist läuft weiter.",
                 level=3, concepts=["upc_einspruch_r19", "upc_aussetzung"],
                 norms=["R. 21.2 VerfO", "R. 295 VerfO", "R. 220.2 VerfO", "R. 19.6 VerfO"],
                 cases=["upc_coa_sunpatent_vivo_aussetzung"], step="step:upc_schema_zustaendigkeit.5"),
        ]),
    ],
)
